export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;

  // State & disturbance estimator variables
  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dx = 0, dy = 0, dz = 0; // Estimated acceleration disturbances
  let uf = 0.45; // Filtered thrust estimate
  let lastThrust = 0.45;
  let intRoll = 0, intPitch = 0;

  // Navigation state
  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let padTimer = 0;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        initialized = true;
      } else {
        // Update filtered motor thrust (nominal lag ~0.04s)
        uf += (lastThrust - uf) * (1 - Math.exp(-dt / 0.04));

        // Compute current thrust direction from measured attitude
        const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
        const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
        const bodyX = sp * cr, bodyZ = -sr;
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = cp * cr;
        const dirZ = -sy * bodyX + cy * bodyZ;

        // Nominal specific thrust alpha0 = 21.4 m/s^2 per unit thrust, nominal drag c0 = 0.58 /s
        const specThrust = Math.max(2.0, 21.4 * uf + (dirY > 0.5 ? dy / dirY : 0));
        const axKnown = specThrust * dirX - 0.58 * vx;
        const ayKnown = 21.4 * uf * dirY - 0.58 * vy - 9.81;
        const azKnown = specThrust * dirZ - 0.58 * vz;

        // Predict
        const pxPred = px + vx * dt + 0.5 * (axKnown + dx) * dt * dt;
        const vxPred = vx + (axKnown + dx) * dt;
        const pyPred = py + vy * dt + 0.5 * (ayKnown + dy) * dt * dt;
        const vyPred = vy + (ayKnown + dy) * dt;
        const pzPred = pz + vz * dt + 0.5 * (azKnown + dz) * dt * dt;
        const vzPred = vz + (azKnown + dz) * dt;

        // Correct x, z
        const epx = p.x - pxPred, evx = v.x - vxPred;
        px = pxPred + 0.55 * epx;
        vx = vxPred + 0.45 * evx + 6.0 * epx;
        if (p.y > 0.09) {
          dx = clamp(dx + 22.0 * evx + 30.0 * epx, -8.5, 8.5);
        }

        const epz = p.z - pzPred, evz = v.z - vzPred;
        pz = pzPred + 0.55 * epz;
        vz = vzPred + 0.45 * evz + 6.0 * epz;
        if (p.y > 0.09) {
          dz = clamp(dz + 22.0 * evz + 30.0 * epz, -8.5, 8.5);
        }

        // Correct y
        const epy = p.y - pyPred, evy = v.y - vyPred;
        py = pyPred + 0.55 * epy;
        vy = vyPred + 0.45 * evy + 6.0 * epy;
        if (p.y > 0.09) {
          dy = clamp(dy + 14.0 * evy + 20.0 * epy, -6.0, 6.0);
        }
      }

      let target = { x: px, y: py, z: pz };
      let tvx = 0, tvy = 0, tvz = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        if (phase === 'align') {
          target = { x: gate.x - 0.38, y: gate.y, z: gate.z };
          const distYZ = Math.hypot(gate.y - py, gate.z - pz);
          const distX = Math.abs(target.x - px);
          const velYZ = Math.hypot(vy, vz);
          if (distYZ < 0.065 && distX < 0.14 && velYZ < 0.25 && Math.abs(vx) < 0.45) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 6) phase = 'cross';
        }
        if (phase === 'cross') {
          // If before gate plane and pushed off center by a sudden gust, pause crossing to re-center
          const timeToCross = Math.max(0.02, (gate.x - px) / Math.max(0.4, vx));
          const predZ = pz + vz * Math.min(0.25, timeToCross);
          const predY = py + vy * Math.min(0.25, timeToCross);
          if (px < gate.x - 0.03 && (Math.abs(predZ - gate.z) > 0.095 || Math.abs(predY - gate.y) > 0.17)) {
            phase = 'align';
            settle = 0;
            target = { x: Math.min(px, gate.x - 0.25), y: gate.y, z: gate.z };
          } else {
            target = { x: gate.x + 0.32, y: gate.y, z: gate.z };
            tvx = 0.6;
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach_pad';
          settle = 0;
        }
        const distXZ = Math.hypot(pad.x - px, pad.z - pz);
        const speedXZ = Math.hypot(vx, vz);
        if (phase === 'approach_pad') {
          // Keep gate 2 y/z clearance briefly until clear of gate 2 frame (x > 1.55)
          if (px < 1.52) {
            target = { x: pad.x, y: 1.05, z: 1.05 + (pad.z - 1.05) * clamp((px - 1.35) / 0.25, 0, 1) };
          } else {
            const h = clamp(0.22 + 0.85 * distXZ, 0.22, 1.05);
            target = { x: pad.x, y: h, z: pad.z };
            if (distXZ < 0.085 && speedXZ < 0.22 && py < 0.35) {
              settle++;
              if (settle >= 5) phase = 'descend';
            } else {
              settle = 0;
            }
          }
        }
        if (phase === 'descend') {
          target = { x: pad.x, y: 0.065, z: pad.z };
          if (distXZ > 0.135 && py > 0.11) {
            // Re-stabilize if a strong gust pushes us near the pad radius before touchdown
            target.y = Math.max(py, 0.18);
          }
          // Once resting on the pad within radius, cut thrust to lock landing
          if (py <= 0.082 && distXZ <= 0.115 && Math.hypot(vx, vy, vz) < 0.38) {
            padTimer++;
            if (padTimer >= 2) {
              lastThrust = 0;
              return {
                thrust: 0,
                roll: clamp(-0.4 * att.roll, -0.08, 0.08),
                pitch: clamp(-0.4 * att.pitch, -0.08, 0.08),
                yawRate: clamp(-1.5 * att.yaw, -0.5, 0.5),
              };
            }
          } else {
            padTimer = 0;
          }
        }
      }

      // Position PD + disturbance rejection + drag compensation
      const ex = target.x - px, ez = target.z - pz, ey = target.y - py;
      const kpXZ = (obs.gateIndex < 3 && phase === 'cross') ? 7.5 : 6.5;
      const kdXZ = (obs.gateIndex < 3 && phase === 'cross') ? 4.8 : 4.4;

      const axCmd = clamp(kpXZ * ex + kdXZ * (tvx - vx) - dx + 0.58 * vx, -4.8, 4.8);
      const azCmd = clamp((obs.gateIndex < 3 ? 8.0 : 6.5) * ez + (obs.gateIndex < 3 ? 5.0 : 4.4) * (tvz - vz) - dz + 0.58 * vz, -4.8, 4.8);

      let ayCmd = clamp(8.5 * ey + 5.2 * (tvy - vy) - dy + 0.58 * vy, -4.5, 5.5);
      if (obs.gateIndex === 3 && phase === 'descend' && py < 0.18) {
        // Gentle descent rate limit near floor
        const vDesY = clamp(2.5 * (0.065 - py), -0.32, 0.25);
        ayCmd = clamp(6.0 * (vDesY - vy) - dy + 0.58 * vy, -3.5, 3.5);
      }

      const totalAy = Math.max(2.5, 9.81 + ayCmd);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bx = (cy * axCmd - sy * azCmd) / totalAy;
      const bz = (sy * axCmd + cy * azCmd) / totalAy;

      const maxTilt = (obs.gateIndex === 3 && phase === 'descend' && py < 0.14) ? 0.16 : 0.52;
      const rollDes = clamp(- Math.asin(clamp(bz, -0.7, 0.7)), -maxTilt, maxTilt);
      const pitchDes = clamp(Math.asin(clamp(bx / Math.max(0.7, Math.cos(rollDes)), -0.7, 0.7)), -maxTilt, maxTilt);

      if (py > 0.09) {
        intRoll = clamp(intRoll + (rollDes - att.roll) * dt * 1.8, -0.15, 0.15);
        intPitch = clamp(intPitch + (pitchDes - att.pitch) * dt * 1.8, -0.15, 0.15);
      }

      const roll = clamp(rollDes + intRoll, -0.6, 0.6);
      const pitch = clamp(pitchDes + intPitch, -0.6, 0.6);

      const tiltFactor = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrust = clamp((9.81 + ayCmd) / (21.4 * tiltFactor), 0.05, 1.0);
      lastThrust = thrust;

      return {
        thrust,
        roll,
        pitch,
        yawRate: clamp(-1.5 * att.yaw, -1.0, 1.0),
      };
    },
  };
}

