export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;

  let initialized = false;
  let zx = 0, zz = 0, zy = 0;
  let integralY = 0;
  let intRoll = 0, intPitch = 0;

  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let padTimer = 0;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;

      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.max(0.5, cp * cr);
      const dirZ = -sy * bodyX + cy * bodyZ;

      const tauD = 0.08;
      if (!initialized) {
        zx = v.x;
        zz = v.z;
        zy = v.y;
        initialized = true;
      }

      // Disturbance estimates from decoupled Q-filter DOB
      const dx = p.y > 0.09 ? clamp((v.x - zx) / tauD, -6.0, 6.0) : 0;
      const dz = p.y > 0.09 ? clamp((v.z - zz) / tauD, -6.0, 6.0) : 0;
      const dy = p.y > 0.09 ? clamp((v.y - zy) / 0.15, -4.5, 4.5) : 0;

      let target;
      let tvx = 0, tvy = 0, tvz = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        if (phase === 'align') {
          target = { x: gate.x - 0.42, y: gate.y, z: gate.z };
          const distYZ = Math.hypot(gate.y - p.y, gate.z - p.z);
          const distX = Math.abs(target.x - p.x);
          if (distYZ < 0.08 && distX < 0.12 && Math.hypot(v.y, v.z) < 0.30 && Math.abs(v.x) < 0.35) {
            settle++;
          } else {
            settle = 0;
          }
          if (settle > 10) phase = 'cross';
        }
        if (phase === 'cross') {
          target = { x: gate.x + 0.35, y: gate.y, z: gate.z };
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach';
          settle = 0;
        }
        target = { x: pad.x, y: 0.85, z: pad.z };
        if (phase !== 'descend' && Math.hypot(target.x - p.x, target.z - p.z) < 0.09 && Math.hypot(v.x, v.z) < 0.22) {
          phase = 'descend';
        }
        if (phase === 'descend') {
          target.y = 0.025;
          if (p.y <= 0.082 && Math.hypot(pad.x - p.x, pad.z - p.z) <= 0.11 && Math.hypot(v.x, v.y, v.z) < 0.35 && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < 0.15) {
            padTimer++;
            if (padTimer >= 3) {
              return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
            }
          } else {
            padTimer = 0;
          }
        }
      }

      const ey = target.y - p.y;
      integralY = clamp(integralY + ey * dt, -0.6, 2.2);
      const ay = clamp(6.0 * ey - 3.8 * v.y + 2.6 * integralY - 0.5 * dy, -3.8, 4.8);

      const ax = clamp(5.2 * (target.x - p.x) + 3.8 * (tvx - v.x) - dx + 0.58 * v.x, -3.8, 3.8);
      const az = clamp(5.6 * (target.z - p.z) + 4.0 * (tvz - v.z) - dz + 0.58 * v.z, -3.8, 3.8);

      // Update DOB internal states using actual measured attitude tilt
      const specVert = Math.max(2.0, 9.81 + ay);
      const aTiltX = specVert * (dirX / dirY);
      const aTiltZ = specVert * (dirZ / dirY);
      if (p.y > 0.09) {
        zx += (aTiltX - 0.58 * v.x + dx) * dt;
        zz += (aTiltZ - 0.58 * v.z + dz) * dt;
        zy += (ay + dy) * dt;
      } else {
        zx = v.x;
        zz = v.z;
        zy = v.y;
      }

      const pitchDes = clamp((cy * ax - sy * az) / 9.81, -0.45, 0.45);
      const rollDes = clamp(-(sy * ax + cy * az) / 9.81, -0.45, 0.45);

      if (p.y > 0.09) {
        intRoll = clamp(intRoll + (rollDes - att.roll) * dt * 1.2, -0.10, 0.10);
        intPitch = clamp(intPitch + (pitchDes - att.pitch) * dt * 1.2, -0.10, 0.10);
      }

      const roll = clamp(rollDes + intRoll, -0.5, 0.5);
      const pitch = clamp(pitchDes + intPitch, -0.5, 0.5);
      const thrust = clamp((0.72 * (9.81 + ay)) / (16 * Math.max(0.7, cr * cp)), 0, 1);

      return { thrust, roll, pitch, yawRate: clamp(-2 * att.yaw, -1.5, 1.5) };
    },
  };
}

