export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;

  let initialized = false;
  let zx = 0, zz = 0;
  let integralY = 0;

  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let padTimer = 0;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;

      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.max(0.5, cp * cr);
      const dirZ = -sy * bodyX + cy * bodyZ;

      const tauD = 0.075;
      if (!initialized) {
        zx = v.x;
        zz = v.z;
        initialized = true;
      }

      // Disturbance estimates from decoupled Q-filter DOB
      const dx = p.y > 0.09 ? clamp((v.x - zx) / tauD, -6.5, 6.5) : 0;
      const dz = p.y > 0.09 ? clamp((v.z - zz) / tauD, -6.5, 6.5) : 0;

      let target;
      let tvx = 0, tvz = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        if (phase === 'align') {
          target = { x: gate.x - 0.34, y: gate.y, z: gate.z };
          const absZ = Math.abs(gate.z - p.z);
          const absY = Math.abs(gate.y - p.y);
          const absX = Math.abs(target.x - p.x);
          if (absZ < 0.055 && absY < 0.09 && absX < 0.11 && Math.abs(v.z) < 0.20 && Math.abs(v.y) < 0.28 && Math.abs(v.x) < 0.35) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 6) phase = 'cross';
        }
        if (phase === 'cross') {
          // Safety abort check if before gate and a gust pushes predicted crossing near frame
          if (p.x < gate.x - 0.015) {
            const tCross = clamp((gate.x - p.x) / Math.max(0.25, v.x), 0.02, 0.35);
            const zPred = p.z + v.z * tCross;
            const yPred = p.y + v.y * tCross;
            if (Math.abs(p.z - gate.z) > 0.082 || Math.abs(zPred - gate.z) > 0.090 ||
                Math.abs(p.y - gate.y) > 0.15 || Math.abs(yPred - gate.y) > 0.17) {
              phase = 'align';
              settle = 0;
              target = { x: gate.x - 0.34, y: gate.y, z: gate.z };
            } else {
              target = { x: gate.x + 0.32, y: gate.y, z: gate.z };
            }
          } else {
            target = { x: gate.x + 0.32, y: gate.y, z: gate.z };
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach';
          settle = 0;
        }
        const distXZ = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedXZ = Math.hypot(v.x, v.z);
        if (phase === 'approach') {
          // Smooth descent after clearing Gate 2 (x > 1.50)
          const h = p.x < 1.50 ? 1.05 : clamp(0.32 + 0.9 * distXZ, 0.32, 0.95);
          target = { x: pad.x, y: h, z: pad.z };
          if (distXZ < 0.095 && speedXZ < 0.24 && p.y < 0.50) {
            settle++;
            if (settle >= 4) phase = 'descend';
          } else {
            settle = 0;
          }
        }
        if (phase === 'descend') {
          target = { x: pad.x, y: 0.02, z: pad.z };
          if (distXZ > 0.135 && p.y > 0.11) {
            target.y = Math.max(p.y, 0.20);
          }
          if (p.y <= 0.085 && distXZ <= 0.12 && Math.hypot(v.x, v.y, v.z) < 0.40 && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < 0.15) {
            padTimer++;
            if (padTimer >= 2) {
              return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
            }
          } else {
            padTimer = 0;
          }
        }
      }

      const ey = target.y - p.y;
      integralY = clamp(integralY + ey * dt, -0.6, 2.2);
      const ayDyn = clamp(6.2 * ey - 4.0 * v.y, -3.5, 4.5);
      const ay = clamp(ayDyn + 2.8 * integralY, -3.8, 5.0);

      // Boost z-axis stiffness near gate crossings
      const nearGate = obs.gateIndex < 3 && Math.abs(obs.nextGate.centre.x - p.x) < 0.45;
      const kpZ = nearGate ? 8.2 : 5.8;
